<script setup>
import {computed} from 'vue'
import {count,mean,percent,tierLabel,n} from '../dataModel.js'
const props=defineProps({rows:{type:Array,default:()=>[]},selected:{type:String,default:'total'},dense:Boolean,unit:{type:String,default:'番'},playerCount:{type:Number,default:4}})
defineEmits(['select'])
const total=computed(()=>props.rows.reduce((s,r)=>s+n(r.total_games),0))
</script>
<template><section class="panel scope-matrix"><div class="panel-heading"><div><h2>场次构成</h2><span class="subtle">同规则、累计样本</span></div><button v-if="selected!=='total'" class="text-button" @click="$emit('select','total')">查看全部</button></div><div v-if="!rows.length" class="inline-empty">暂无场次数据</div><div v-else-if="!dense" class="scope-bars"><button v-for="(r,i) in rows" :key="r.match_tier" :class="{active:selected===r.match_tier}" @click="$emit('select',r.match_tier)"><span class="scope-label"><i :class="'series-'+i"/>{{r.label||tierLabel(r.match_tier)}}</span><span class="scope-track"><i :style="{width:percent(r.total_games,total),opacity:1-i*.12}"/></span><strong>{{count(r.total_games)}}</strong><small>{{percent(r.total_games,total)}}</small></button></div><div v-else class="table-scroll"><table><thead><tr><th>场次</th><th class="numeric">对局</th><th class="numeric">小局</th><th class="numeric">自摸占和牌</th><th class="numeric">平均和牌值</th><th class="numeric">副露率</th></tr></thead><tbody><tr v-for="r in rows" :key="r.match_tier" :class="{active:selected===r.match_tier}"><td><button class="text-button" @click="$emit('select',r.match_tier)">{{r.label||tierLabel(r.match_tier)}}</button></td><td class="numeric">{{count(r.total_games)}}</td><td class="numeric">{{count(r.total_rounds)}}</td><td class="numeric">{{percent(r.self_draw_count,r.win_count)}}</td><td class="numeric">{{unit?mean(r.total_fan_score,r.win_count):'—'}} {{unit}}</td><td class="numeric">{{percent(r.fulu_round_count,r.total_rounds*playerCount)}}</td></tr></tbody></table></div><p class="panel-footnote">选择场次同步查看对应趋势与牌谱。副露率按 {{playerCount}} 位玩家的小局总数计算。</p></section></template>
